description:
NodeGUI — фреймворк, который позволяет писать нативные кроссплатформенные десктопные приложения. Под капотом он использует Qt для отрисовки интерфейса. Есть возможность подключить React или Vue . Также существует имплементация с Angular от irustm . Эта статья будет опираться именно на версию с React. Запуск и настройка Сначала необходимо установить cmake . Склонируем готовый шаблон от разработчиков и запустим его. npm install
npm run dev
npm start Чтобы приложение пересобиралось каждый раз, как в код вносятся изменения, к компоненту app подключается hot reload. if (module.hot) {
 module.hot.accept(['./app'], function () {
   Renderer.forceUpdate();
 });
} К сожалению, если сохранить файл с какими-либо синтаксическими ошибками, сборка упадет и придется поднимать приложение заново. К тому же, указанный компонент обязательно должен быть классовым (только app, любые его дочерние компоненты могут быть функциональными).

Со вчерашнего дня, господа, можно написать вот такой скрипт: // функция преобразования строки JavaScript (UTF-8) в UTF-16
function TEXT(text){
   return new Buffer(text, 'ucs2').toString('binary');
}

var FFI = require('node-ffi');

// подключаемся к user32.dll
var user32 = new FFI.Library('user32', {
   'MessageBoxW': [
      'int32', [ 'int32', 'string', 'string', 'int32' ]
   ]
});

// диалоговое окно
var OK_or_Cancel = user32.MessageBoxW(
   0, TEXT('Привет, Хабрахабр!'), TEXT('Заголовок окна'), 1
); и, запустив его в Windows, получить желаемый результат — диалоговое окно Windows. Это стало возможным потому, что модуль node-ffi (обёртку вокруг той необыкновенно полезной библиотеки libffi , которая используется для вызова библиотек на языке Си не менее чем в восьми других языках) вчера портировали на Windows.
